import { metricsClient, monitoredEntitiesClient } from '@dynatrace-sdk/client-classic-environment-v2';

// ---- Dashboard timeframe -> epoch ms ----
// Dashboards pass the timeframe to the tile function as context.$dt_timeframe_from / $dt_timeframe_to (ISO timestamps).
// The "$dt_timeframe_*" text substitution below is a backup; if neither is available the tiles use the last 30 days.
const TF_FROM = "$dt_timeframe_from";
const TF_TO = "$dt_timeframe_to";
const UNIT_MS = { s: 1e3, m: 6e4, h: 36e5, d: 864e5, w: 6048e5, M: 2592e6, y: 31536e6 };
function toMs(value, fallback) {
  if (typeof value === 'number' && isFinite(value)) return value;
  if (value instanceof Date && !isNaN(value)) return value.getTime();
  const expr = value == null ? '' : String(value).trim();
  if (!expr || expr.startsWith('$')) return fallback;
  const iso = Date.parse(expr);
  if (!isNaN(iso)) return iso;
  const m = expr.replace(/\s/g, '').match(/^now(?:\(\))?(?:([-+])(\d+)([smhdwMy]))?(?:@\w+)?$/);
  if (!m) return fallback;
  return m[1] ? Date.now() + (m[1] === '-' ? -1 : 1) * Number(m[2]) * UNIT_MS[m[3]] : Date.now();
}
let TO = Date.now();
let FROM = TO - 30 * UNIT_MS.d;
let TF_SOURCE = 'default: last 30 days';
// Called first in every tile with the tile function's argument.
function useTimeframe(context) {
  const c = (context && typeof context === 'object') ? context : {};
  const v = (c.variables && typeof c.variables === 'object') ? c.variables : {};
  const pick = (k) => [c['$' + k], c[k], v['$' + k], v[k]].find((x) => x != null && x !== '');
  const ctxFrom = pick('dt_timeframe_from'), ctxTo = pick('dt_timeframe_to');
  const from = ctxFrom != null ? ctxFrom : TF_FROM, to = ctxTo != null ? ctxTo : TF_TO;
  TO = toMs(to, Date.now());
  FROM = toMs(from, TO - 30 * UNIT_MS.d);
  if (FROM >= TO) FROM = TO - 30 * UNIT_MS.d;
  TF_SOURCE = (ctxFrom != null || ctxTo != null) ? 'dashboard timeframe (context)'
    : (!TF_FROM.startsWith('$') || !TF_TO.startsWith('$')) ? 'dashboard timeframe (variables)' : 'default: last 30 days';
}

// ---- DEM unit weights (classic DEM rate card) - align with your contract ----
const DEM_WEIGHTS = {
  webSession: 0.25, webSessionReplay: 1.0, webUserActionProperty: 0.01,
  mobileSession: 0.25, mobileSessionReplay: 1.0, mobileUserActionProperty: 0.01,
  customSession: 0.25, customUserActionProperty: 0.01,
  browserAction: 1.0, httpRequest: 0.1, thirdPartyResult: 0.1,
};

// ---- Metrics API v2 query. Returns [] instead of failing; errors, and warnings on empty results
// (e.g. "the metric has no such key"), are kept in PROBLEMS so tables can show them. ----
const PROBLEMS = [];
async function q(metricSelector, resolution = 'Inf', extra = {}) {
  try {
    const res = await metricsClient.query({
      acceptType: 'application/json; charset=utf-8',
      metricSelector, resolution, from: String(FROM), to: String(TO), ...extra,
    });
    const data = (res.result && res.result[0] && res.result[0].data) || [];
    if (!data.length && res.warnings && res.warnings.length) PROBLEMS.push(res.warnings[0]);
    return data;
  } catch (e) {
    PROBLEMS.push((e && e.body && e.body.error && e.body.error.message) || (e && e.message) || String(e));
    console.warn('Metric query failed: ' + metricSelector, e);
    return [];
  }
}
// Dimension keys differ between environments (e.g. "Metric Key" vs "metric_key"), so no selector names a
// dimension: series keep all their dimensions and the entity / key is read from whatever is there.
// Billing metrics only support the auto/value aggregations, so sort by value(auto, …).
const NAMES = ':names';
const TOP = (n) => ':sort(value(auto,descending)):limit(' + n + ')';
const ENTITY_ID = /^[A-Z][A-Z0-9_]*-[0-9A-F]{16}$/;
const firstDim = (s) => Object.entries(s.dimensionMap || {}).filter(([k]) => !k.endsWith('.name'))
  .map(([, v]) => v).filter(Boolean)[0] || '';
const entityOf = (s) => {
  const m = s.dimensionMap || {};
  const k = Object.keys(m).find((key) => ENTITY_ID.test(m[key] || ''));
  return k ? { id: m[k], name: m[k + '.name'] || m[k] } : { id: '', name: firstDim(s) || 'Unattributed' };
};
const sumVals = (s) => (s.values || []).reduce((a, v) => a + (v ?? 0), 0);
const total = (series) => series.reduce((a, s) => a + sumVals(s), 0);
const round = (n, d = 2) => Math.round(n * 10 ** d) / 10 ** d;
// Charts lose their field mapping on an empty result ("The field ... is no longer available"),
// so chart tiles return one zero-valued placeholder row when there is no data.
const NO_DATA = 'No data in timeframe';
// Day label for bar-chart categories. An ISO date such as "2026-11-24" is detected as a timestamp, which a
// categorical chart cannot use as its category ("The field \"Day\" is no longer available"), so use "24 Nov ’26".
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
// Daily charts use days in UTC+8 (00:00–24:00 UTC+8). Values are fetched per hour; the Metrics API stamps each value with
// the END of its hour, so a value belongs to the day in which its hour STARTED.
