const dayKey = (t) => localDay(t).toISOString().slice(0, 10);
const dayLabel = (t) => { const d = localDay(t);
  return String(d.getUTCDate()).padStart(2, '0') + ' ' + MONTHS[d.getUTCMonth()] + ' ’' + String(d.getUTCFullYear()).slice(2); };
// Hourly data is needed to cut UTC+8 days; above ~400 days fall back to daily (UTC) buckets to stay within API limits.
const dailyResolution = () => (TO - FROM <= 400 * UNIT_MS.d ? '1h' : '1d');
const fmtTZ = (t) => new Date(t + DAY_TZ_OFFSET_H * UNIT_MS.h).toISOString().slice(0, 16).replace('T', ' ') + ' ' + DAY_TZ;
const byDate = (byDay) => Object.entries(byDay).sort(([a], [b]) => a.localeCompare(b)).map(([, r]) => r);
const orPlaceholder = (rows, placeholder) => (rows.length ? rows : [placeholder]);
// Text for the first column of an empty table / chart: the API problem if there was one, else "No data".
const problem = () => (PROBLEMS.length ? 'Query problem: ' + PROBLEMS[0] : NO_DATA);
const ENTITY_TYPES = {
  HOST: 'Host', SERVICE: 'Service', PROCESS_GROUP: 'Process group', PROCESS_GROUP_INSTANCE: 'Process',
  CUSTOM_DEVICE: 'Custom device', CUSTOM_DEVICE_GROUP: 'Custom device group', APPLICATION: 'Web application',
  MOBILE_APPLICATION: 'Mobile application', CUSTOM_APPLICATION: 'Custom application',
  SYNTHETIC_TEST: 'Browser monitor', HTTP_CHECK: 'HTTP monitor', CLOUD_APPLICATION: 'K8s workload',
  CLOUD_APPLICATION_NAMESPACE: 'K8s namespace', KUBERNETES_CLUSTER: 'K8s cluster', KUBERNETES_NODE: 'K8s node',
  AWS_LAMBDA_FUNCTION: 'AWS Lambda', AZURE_FUNCTION_APP: 'Azure Function', ENVIRONMENT: 'Environment',
};
const entityType = (id) => {
  if (!id) return 'Unattributed';
  const p = id.replace(/-[0-9A-F]{16}$/i, '');
  return ENTITY_TYPES[p] || p.replace(/_/g, ' ').toLowerCase();
};

export default async function (context) {
  useTimeframe(context);
  const POOLS = [["Metrics", "builtin:billing.ddu.metrics.total"], ["Log Monitoring", "builtin:billing.ddu.log.total"], ["Events", "builtin:billing.ddu.events.total"], ["Traces", "builtin:billing.ddu.traces.total"], ["Serverless", "builtin:billing.ddu.serverless.total"]];
  let ddu = 0;
  for (const [, key] of POOLS) ddu += total(await q(key));
  return [{ "Total DDU": round(ddu) }];
}

