// ---- Dashboard timeframe -> epoch ms ----
// Dashboards pass the timeframe to the tile function as context.$dt_timeframe_from / $dt_timeframe_to (ISO timestamps).
// The "$dt_timeframe_*" text substitution below is a backup; if neither is available the tiles use the last 30 days.
const TF_FROM = "$dt_timeframe_from";
const TF_TO = "$dt_timeframe_to";
const UNIT_MS = { s: 1e3, m: 6e4, h: 36e5, d: 864e5, w: 6048e5, M: 2592e6, y: 31536e6 };
function toMs(value, fallback) {
  if (typeof value === 'number' && isFinite(value)) return value;
  if (value instanceof Date && !isNaN(value)) return value.getTime();
  const expr = value == null ? '' : String(value).trim();
  if (!expr || expr.startsWith('$')) return fallback;
  const iso = Date.parse(expr);
  if (!isNaN(iso)) return iso;
  const m = expr.replace(/\s/g, '').match(/^now(?:\(\))?(?:([-+])(\d+)([smhdwMy]))?(?:@\w+)?$/);
  if (!m) return fallback;
  return m[1] ? Date.now() + (m[1] === '-' ? -1 : 1) * Number(m[2]) * UNIT_MS[m[3]] : Date.now();
}
let TO = Date.now();
let FROM = TO - 30 * UNIT_MS.d;
let TF_SOURCE = 'default: last 30 days';
// Called first in every tile with the tile function's argument.
function useTimeframe(context) {
  const c = (context && typeof context === 'object') ? context : {};
  const v = (c.variables && typeof c.variables === 'object') ? c.variables : {};
  const pick = (k) => [c['$' + k], c[k], v['$' + k], v[k]].find((x) => x != null && x !== '');
  const ctxFrom = pick('dt_timeframe_from'), ctxTo = pick('dt_timeframe_to');
  const from = ctxFrom != null ? ctxFrom : TF_FROM, to = ctxTo != null ? ctxTo : TF_TO;
  TO = toMs(to, Date.now());
  FROM = toMs(from, TO - 30 * UNIT_MS.d);
  if (FROM >= TO) FROM = TO - 30 * UNIT_MS.d;
  TF_SOURCE = (ctxFrom != null || ctxTo != null) ? 'dashboard timeframe (context)'
    : (!TF_FROM.startsWith('$') || !TF_TO.startsWith('$')) ? 'dashboard timeframe (variables)' : 'default: last 30 days';
}

// ---- DEM unit weights (classic DEM rate card) - align with your contract ----
const DEM_WEIGHTS = {
  webSession: 0.25, webSessionReplay: 1.0, webUserActionProperty: 0.01,
  mobileSession: 0.25, mobileSessionReplay: 1.0, mobileUserActionProperty: 0.01,
  customSession: 0.25, customUserActionProperty: 0.01,
  browserAction: 1.0, httpRequest: 0.1, thirdPartyResult: 0.1,
