import { metricsClient, monitoredEntitiesClient } from '@dynatrace-sdk/client-classic-environment-v2';

// ---- Dashboard timeframe -> epoch ms ----
// Dashboards pass the timeframe to the tile function as context.$dt_timeframe_from / $dt_timeframe_to (ISO timestamps).
// The "$dt_timeframe_*" text substitution below is a backup; if neither is available the tiles use the last 30 days.
const TF_FROM = "$dt_timeframe_from";
const TF_TO = "$dt_timeframe_to";
const UNIT_MS = { s: 1e3, m: 6e4, h: 36e5, d: 864e5, w: 6048e5, M: 2592e6, y: 31536e6 };
function toMs(value, fallback) {
  if (typeof value === 'number' && isFinite(value)) return value;
  if (value instanceof Date && !isNaN(value)) return value.getTime();
  const expr = value == null ? '' : String(value).trim();
  if (!expr || expr.startsWith('$')) return fallback;
  const iso = Date.parse(expr);
  if (!isNaN(iso)) return iso;
  const m = expr.replace(/\s/g, '').match(/^now(?:\(\))?(?:([-+])(\d+)([smhdwMy]))?(?:@\w+)?$/);
  if (!m) return fallback;
  return m[1] ? Date.now() + (m[1] === '-' ? -1 : 1) * Number(m[2]) * UNIT_MS[m[3]] : Date.now();
}
let TO = Date.now();
let FROM = TO - 30 * UNIT_MS.d;
let TF_SOURCE = 'default: last 30 days';
// Called first in every tile with the tile function's argument.
function useTimeframe(context) {
  const c = (context && typeof context === 'object') ? context : {};
  const v = (c.variables && typeof c.variables === 'object') ? c.variables : {};
  const pick = (k) => [c['$' + k], c[k], v['$' + k], v[k]].find((x) => x != null && x !== '');
  const ctxFrom = pick('dt_timeframe_from'), ctxTo = pick('dt_timeframe_to');
  const from = ctxFrom != null ? ctxFrom : TF_FROM, to = ctxTo != null ? ctxTo : TF_TO;
  TO = toMs(to, Date.now());
  FROM = toMs(from, TO - 30 * UNIT_MS.d);
  if (FROM >= TO) FROM = TO - 30 * UNIT_MS.d;
  TF_SOURCE = (ctxFrom != null || ctxTo != null) ? 'dashboard timeframe (context)'
    : (!TF_FROM.startsWith('$') || !TF_TO.startsWith('$')) ? 'dashboard timeframe (variables)' : 'default: last 30 days';
}

// ---- DEM unit weights (classic DEM rate card) - align with your contract ----
const DEM_WEIGHTS = {
  webSession: 0.25, webSessionReplay: 1.0, webUserActionProperty: 0.01,
  mobileSession: 0.25, mobileSessionReplay: 1.0, mobileUserActionProperty: 0.01,
  customSession: 0.25, customUserActionProperty: 0.01,
  browserAction: 1.0, httpRequest: 0.1, thirdPartyResult: 0.1,
};

// ---- Metrics API v2 query. Returns [] instead of failing; errors, and warnings on empty results
// (e.g. "the metric has no such key"), are kept in PROBLEMS so tables can show them. ----
const PROBLEMS = [];
async function q(metricSelector, resolution = 'Inf', extra = {}) {
  try {
    const res = await metricsClient.query({
      acceptType: 'application/json; charset=utf-8',
      metricSelector, resolution, from: String(FROM), to: String(TO), ...extra,
    });
    const data = (res.result && res.result[0] && res.result[0].data) || [];
    if (!data.length && res.warnings && res.warnings.length) PROBLEMS.push(res.warnings[0]);
    return data;
  } catch (e) {
    PROBLEMS.push((e && e.body && e.body.error && e.body.error.message) || (e && e.message) || String(e));
    console.warn('Metric query failed: ' + metricSelector, e);
    return [];
  }
}
// Dimension keys differ between environments (e.g. "Metric Key" vs "metric_key"), so no selector names a
// dimension: series keep all their dimensions and the entity / key is read from whatever is there.
// Billing metrics only support the auto/value aggregations, so sort by value(auto, …).
const NAMES = ':names';
const TOP = (n) => ':sort(value(auto,descending)):limit(' + n + ')';
const ENTITY_ID = /^[A-Z][A-Z0-9_]*-[0-9A-F]{16}$/;
const firstDim = (s) => Object.entries(s.dimensionMap || {}).filter(([k]) => !k.endsWith('.name'))
  .map(([, v]) => v).filter(Boolean)[0] || '';
const entityOf = (s) => {
  const m = s.dimensionMap || {};
  const k = Object.keys(m).find((key) => ENTITY_ID.test(m[key] || ''));
  return k ? { id: m[k], name: m[k + '.name'] || m[k] } : { id: '', name: firstDim(s) || 'Unattributed' };
};
const sumVals = (s) => (s.values || []).reduce((a, v) => a + (v ?? 0), 0);
const total = (series) => series.reduce((a, s) => a + sumVals(s), 0);
const round = (n, d = 2) => Math.round(n * 10 ** d) / 10 ** d;
// Charts lose their field mapping on an empty result ("The field ... is no longer available"),
// so chart tiles return one zero-valued placeholder row when there is no data.
const NO_DATA = 'No data in timeframe';
// Day label for bar-chart categories. An ISO date such as "2026-11-24" is detected as a timestamp, which a
// categorical chart cannot use as its category ("The field \"Day\" is no longer available"), so use "24 Nov ’26".
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
// Daily charts use days in UTC+8 (00:00–24:00 UTC+8). Values are fetched per hour; the Metrics API stamps each value with
// the END of its hour, so a value belongs to the day in which its hour STARTED.
const DAY_TZ_OFFSET_H = 8;
const DAY_TZ = 'UTC+8';
const localDay = (t) => new Date(t - UNIT_MS.h + DAY_TZ_OFFSET_H * UNIT_MS.h); // read with getUTC* = UTC+8 calendar
const dayKey = (t) => localDay(t).toISOString().slice(0, 10);
const dayLabel = (t) => { const d = localDay(t);
  return String(d.getUTCDate()).padStart(2, '0') + ' ' + MONTHS[d.getUTCMonth()] + ' ’' + String(d.getUTCFullYear()).slice(2); };
// Hourly data is needed to cut UTC+8 days; above ~400 days fall back to daily (UTC) buckets to stay within API limits.
const dailyResolution = () => (TO - FROM <= 400 * UNIT_MS.d ? '1h' : '1d');
const fmtTZ = (t) => new Date(t + DAY_TZ_OFFSET_H * UNIT_MS.h).toISOString().slice(0, 16).replace('T', ' ') + ' ' + DAY_TZ;
const byDate = (byDay) => Object.entries(byDay).sort(([a], [b]) => a.localeCompare(b)).map(([, r]) => r);
const orPlaceholder = (rows, placeholder) => (rows.length ? rows : [placeholder]);
// Text for the first column of an empty table / chart: the API problem if there was one, else "No data".
const problem = () => (PROBLEMS.length ? 'Query problem: ' + PROBLEMS[0] : NO_DATA);
const ENTITY_TYPES = {
  HOST: 'Host', SERVICE: 'Service', PROCESS_GROUP: 'Process group', PROCESS_GROUP_INSTANCE: 'Process',
  CUSTOM_DEVICE: 'Custom device', CUSTOM_DEVICE_GROUP: 'Custom device group', APPLICATION: 'Web application',
  MOBILE_APPLICATION: 'Mobile application', CUSTOM_APPLICATION: 'Custom application',
  SYNTHETIC_TEST: 'Browser monitor', HTTP_CHECK: 'HTTP monitor', CLOUD_APPLICATION: 'K8s workload',
  CLOUD_APPLICATION_NAMESPACE: 'K8s namespace', KUBERNETES_CLUSTER: 'K8s cluster', KUBERNETES_NODE: 'K8s node',
  AWS_LAMBDA_FUNCTION: 'AWS Lambda', AZURE_FUNCTION_APP: 'Azure Function', ENVIRONMENT: 'Environment',
};
const entityType = (id) => {
  if (!id) return 'Unattributed';
  const p = id.replace(/-[0-9A-F]{16}$/i, '');
  return ENTITY_TYPES[p] || p.replace(/_/g, ' ').toLowerCase();
};

export default async function (context) {
  useTimeframe(context);
  const KEYS = [
    'builtin:billing.ddu.metrics.total', 'builtin:billing.ddu.metrics.byEntity', 'builtin:billing.ddu.metrics.byMetric',
    'builtin:billing.ddu.metrics.byEntityRaw', 'builtin:billing.ddu.includedMetricDduPerHost',
    'builtin:billing.ddu.log.total', 'builtin:billing.ddu.log.byEntity', 'builtin:billing.ddu.log.byDescription',
    'builtin:billing.ddu.events.total', 'builtin:billing.ddu.events.byEntity', 'builtin:billing.ddu.events.byDescription',
    'builtin:billing.ddu.traces.total', 'builtin:billing.ddu.traces.byEntity', 'builtin:billing.ddu.traces.byDescription',
    'builtin:billing.ddu.serverless.total', 'builtin:billing.ddu.serverless.byEntity', 'builtin:billing.ddu.serverless.byDescription',
    'builtin:billing.apps.web.sessionsWithoutReplayByApplication', 'builtin:billing.apps.web.sessionsWithReplayByApplication',
    'builtin:billing.apps.web.userActionPropertiesByApplication',
    'builtin:billing.apps.mobile.sessionsWithoutReplayByApplication', 'builtin:billing.apps.mobile.sessionsWithReplayByApplication',
    'builtin:billing.apps.mobile.userActionPropertiesByMobileApplication',
    'builtin:billing.apps.custom.sessionsWithoutReplayByApplication', 'builtin:billing.apps.custom.userActionPropertiesByDeviceApplication',
    'builtin:billing.synthetic.actions', 'builtin:billing.synthetic.requests', 'builtin:billing.synthetic.external',
    'dsfm:billing.hostunit.connected', 'dsfm:billing.hostunit.assigned',
  ];
  const rows = [{ "Metric key": 'Timeframe used by the tiles', Status: TF_SOURCE,
    "Total in timeframe": null, Dimensions: fmtTZ(FROM) + ' → ' + fmtTZ(TO), Aggregations: '' }];
  try {
    const r = await monitoredEntitiesClient.getEntities({ entitySelector: 'type("HOST")',
      fields: '+properties.monitoringMode,+properties.physicalMemory,+properties.state', pageSize: 500,
      from: String(TO - 2 * UNIT_MS.h), to: String(TO) });
    const modes = {}; let noMem = 0;
    for (const e of r.entities || []) { const m = (e.properties && e.properties.monitoringMode) || 'not reported'; modes[m] = (modes[m] || 0) + 1;
      if (!(e.properties && e.properties.physicalMemory)) noMem += 1; }
    rows.push({ "Metric key": 'Entities API: host monitoringMode, physicalMemory, state (first 500 hosts, 2 h before timeframe end)',
      Status: !r.totalCount ? 'No hosts' : noMem ? 'OK, ' + noMem + ' host(s) without physicalMemory (counted as 0 HU)' : 'OK',
      "Total in timeframe": r.totalCount || 0, Dimensions: Object.entries(modes).map(([m, n]) => m + ': ' + n).join(', '), Aggregations: '' });
  } catch (e) {
